// How do I find out what kind of object a border style is in a document?

// Identify the category of a border style and display the result in a document.

let doc = Api.GetDocument();
let paragraph = doc.GetElement(0);
let rgbColor = Api.RGB(255, 111, 61);
let fill = Api.CreateSolidFill(rgbColor);
let stroke = Api.CreateStroke(5 * 36000, Api.CreateSolidFill(Api.RGB(51, 51, 51)));
let drawing = Api.CreateShape("roundRect", 5930900, 395605, fill, stroke);
paragraph.AddDrawing(drawing);
let classType = stroke.GetClassType();
paragraph = Api.CreateParagraph();
paragraph.AddText("Class Type = " + classType);
doc.Push(paragraph);

// How do I find out what dash pattern is applied to a shape's border in a document?

// Retrieve and display the line dash style used on a shape border in a document.

let doc = Api.GetDocument();
let paragraph = doc.GetElement(0);
let fill = Api.CreateSolidFill(Api.CreateRGBColor(255, 200, 100));
let stroke = Api.CreateStroke(36000, Api.CreateSolidFill(Api.CreateRGBColor(0, 0, 255)));
let shape = Api.CreateShape("rect", 100 * 36000, 50 * 36000, fill, stroke);
paragraph.AddDrawing(shape);
paragraph.AddLineBreak();
let retrievedStroke = shape.GetLine();
let dashType = retrievedStroke.GetDashType();
paragraph.AddText("Dash type: " + (dashType ? dashType : "not set"));

// How do I read the color used for a shape's border fill in a document?

// Extract and display the fill type from a shape's border to inspect its color settings in a document.

let doc = Api.GetDocument();
let paragraph = doc.GetElement(0);
let fill = Api.CreateSolidFill(Api.CreateRGBColor(255, 200, 100));
let stroke = Api.CreateStroke(2 * 36000, Api.CreateSolidFill(Api.CreateRGBColor(0, 0, 255)));
let shape = Api.CreateShape("rect", 100 * 36000, 50 * 36000, fill, stroke);
paragraph.AddDrawing(shape);
paragraph.AddLineBreak();
let strokeObj = shape.GetLine();
if (strokeObj) {
    let strokeFill = strokeObj.GetFill();
    if (strokeFill) {
        paragraph.AddText("Stroke fill type: " + strokeFill.GetType());
    }
}

// How do I find out how thick a shape's border is in a document?

// Check the measured thickness of each shape's outline in a document.

let doc = Api.GetDocument();
let paragraph = doc.GetElement(0);

// Shape with 1pt border
let fill = Api.CreateSolidFill(Api.CreateRGBColor(255, 200, 100));
let stroke1 = Api.CreateStroke(1 * 12700, Api.CreateSolidFill(Api.CreateRGBColor(0, 0, 255)));
let shape1 = Api.CreateShape("rect", 50 * 36000, 30 * 36000, fill, stroke1);
paragraph.AddDrawing(shape1);
let width1 = shape1.GetLine().GetWidth();
paragraph.AddText("Border 1: " + width1 + " EMU (" + (width1 / 12700).toFixed(2) + " pt)");
paragraph.AddLineBreak();

// Shape with 2.5pt border
let stroke2 = Api.CreateStroke(2.5 * 12700, Api.CreateSolidFill(Api.CreateRGBColor(255, 0, 0)));
let shape2 = Api.CreateShape("rect", 50 * 36000, 30 * 36000, fill, stroke2);
paragraph.AddDrawing(shape2);
let width2 = shape2.GetLine().GetWidth();
paragraph.AddText("Border 2: " + width2 + " EMU (" + (width2 / 12700).toFixed(2) + " pt)");
paragraph.AddLineBreak();

// Shape with 5pt border
let stroke3 = Api.CreateStroke(5 * 12700, Api.CreateSolidFill(Api.CreateRGBColor(0, 255, 0)));
let shape3 = Api.CreateShape("rect", 50 * 36000, 30 * 36000, fill, stroke3);
paragraph.AddDrawing(shape3);
let width3 = shape3.GetLine().GetWidth();
paragraph.AddText("Border 3: " + width3 + " EMU (" + (width3 / 12700).toFixed(2) + " pt)");

// How do I export and restore a border style for reuse in a document?

// Preserve a border configuration so it can be applied again later in a document.

let doc = Api.GetDocument();
let paragraph = doc.GetElement(0);
let rgbColor = Api.RGB(255, 111, 61);
let fill = Api.CreateSolidFill(rgbColor);
let stroke = Api.CreateStroke(5 * 36000, Api.CreateSolidFill(Api.RGB(51, 51, 51)));
let json = stroke.ToJSON();
let strokeFromJSON = Api.FromJSON(json);
let drawing = Api.CreateShape("roundRect", 5930900, 395605, fill, strokeFromJSON);
paragraph.AddDrawing(drawing);
